        assert_eq!(vars.get("KEY"), Some(&"a=b=c".to_string()));
    }

    // --- Edge cases: duplicate keys and ordering ---

    #[test]
    fn duplicate_keys_last_value_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    // --- Edge cases: empty and whitespace-only input ---

    #[test]
    fn empty_input_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_and_blank_lines_returns_empty_map() {
        let content = "# comment\n\n# another\n  \n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    // --- Edge cases: file I/O ---

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join(".env");
        std::fs::write(&path, "FROM_FILE=hello\nNUMBER=42").unwrap();

        let vars = EnvFileParser::load(&path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"hello".to_string()));
        assert_eq!(vars.get("NUMBER"), Some(&"42".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join(".env");
        std::fs::write(&path, "OPTIONAL=yes").unwrap();

        let vars = EnvFileParser::load_optional(&path).unwrap();
        assert_eq!(vars.get("OPTIONAL"), Some(&"yes".to_string()));
    }
}
